/*
 * A038550  Products of an odd prime and a power of two (sorted).
 * https://oeis.org/A038550
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, nice
 * Formula:   not stated
 * Range:     u8 n <= 119, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 *  Sequence A038550: Numbers that equal an odd prime times a power of two.
 *  Generated by scanning integers and keeping those whose odd part is a prime ≥3.
 */
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/is_prime.h"

seq_t a(idx_t n)
{
    /* Static cache for memoisation of the sequence */
    static seq_t *cache = NULL;          /* cache[0] is a(1) */
    static size_t cache_len = 0;         /* number of cached terms */
    static size_t cache_cap = 0;         /* current capacity of the cache */
    static idx_t last_checked = 3;       /* next integer to test */

    /* Extend the cache until it contains term n */
    while (cache_len < n) {
        for (;;) {
            idx_t m = last_checked++;

            /* Extract the odd part of m */
            idx_t odd = m;
            while ((odd & 1) == 0)
                odd >>= 1;

            if (odd >= 3 && is_prime(odd)) {
                /* Ensure enough room in the cache */
                if (cache_len == cache_cap) {
                    size_t new_cap = cache_cap ? cache_cap * 2 : 128;
                    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                    if (!tmp)
                        abort(); /* allocation failure */
                    cache = tmp;
                    cache_cap = new_cap;
                }
                /* Store the term */
                cache[cache_len++] = (seq_t)m;
                break; /* advance to next missing term */
            }
        }
    }

    return cache[n - 1];
}
